package com.aoo.bcg.common.club;
import java.sql.Connection;import java.util.Objects;import javax.sql.DataSource;
import com.aoo.bcg.common.concurrency.LockOrderGuard;
/** Serializes member/template invariants on one club guard row, preventing phantom and write skew. */
public final class ClubAggregateTransaction{private final DataSource source;public ClubAggregateTransaction(DataSource source){this.source=Objects.requireNonNull(source);}public <T>T execute(long clubId,Work<T>work){if(clubId<=0||work==null)throw new IllegalArgumentException("invalid club transaction");try(var club=LockOrderGuard.enter(LockOrderGuard.Level.CLUB,Long.toUnsignedString(clubId));var database=LockOrderGuard.enter(LockOrderGuard.Level.DATABASE,"primary");var connection=source.getConnection()){connection.setAutoCommit(false);try{try(var insert=connection.prepareStatement("INSERT IGNORE INTO aoo_club_guard(club_id,row_version) VALUES(?,1)")){insert.setLong(1,clubId);insert.executeUpdate();}try(var lock=connection.prepareStatement("SELECT row_version FROM aoo_club_guard WHERE club_id=? FOR UPDATE")){lock.setLong(1,clubId);try(var rows=lock.executeQuery()){if(!rows.next())throw new IllegalStateException("club guard missing");}}T result=work.apply(connection);try(var update=connection.prepareStatement("UPDATE aoo_club_guard SET row_version=row_version+1 WHERE club_id=?")){update.setLong(1,clubId);update.executeUpdate();}connection.commit();return result;}catch(Exception error){connection.rollback();throw error;}finally{connection.setAutoCommit(true);}}catch(Exception error){throw new IllegalStateException("club aggregate transaction failed",error);}}@FunctionalInterface public interface Work<T>{T apply(Connection connection)throws Exception;}}
